require_once __DIR__.'/../../includes/comercial.php';exigir_comercial_admin();$db=obtener_conexion();$periodo=(string)($_GET['periodo']??'mensual');$hoy=new DateTimeImmutable('today');if($periodo==='semanal'){$inicio=$hoy->modify('-6 days');$fin=$hoy;}elseif($periodo==='anual'){$inicio=$hoy->setDate((int)$hoy->format('Y'),1,1);$fin=$hoy;}elseif($periodo==='personalizado'&&fecha_valida($_GET['desde']??'')&&fecha_valida($_GET['hasta']??'')){$inicio=new DateTimeImmutable($_GET['desde']);$fin=new DateTimeImmutable($_GET['hasta']);}else{$inicio=$hoy->modify('first day of this month');$fin=$hoy;$periodo='mensual';}$desde=$inicio->format('Y-m-d');$hasta=$fin->format('Y-m-d');$ingresos=ingresos_periodo($db,$desde.' 00:00:00',$hasta.' 23:59:59');$s=$db->prepare('SELECT DATE(fecha) dia,SUM(total) total FROM venta WHERE fecha>=? AND fecha<=? GROUP BY DATE(fecha) ORDER BY dia');$s->execute([$desde.' 00:00:00',$hasta.' 23:59:59']);$serie=[];foreach($s->fetchAll() as $r)$serie[$r['dia']]=(float)$r['total'];$s=$db->prepare('SELECT DATE(fecha) dia,SUM(monto) total FROM cobro WHERE fecha>=? AND fecha<=? GROUP BY DATE(fecha) ORDER BY dia');$s->execute([$desde.' 00:00:00',$hasta.' 23:59:59']);foreach($s->fetchAll() as $r)$serie[$r['dia']]=($serie[$r['dia']]??0)+(float)$r['total'];ksort($serie);$stock=$db->query('SELECT m.*,p.nombre AS proveedor_nombre FROM material m LEFT JOIN proveedor p ON p.id_proveedor=m.id_proveedor ORDER BY m.stock<=m.stock_minimo DESC,m.nombre')->fetchAll();$ventas=$db->query('SELECT v.*,c.nombre AS cliente_nombre,i.codigo_qr,i.tipo FROM venta v INNER JOIN cliente c ON c.id_cliente=v.id_cliente LEFT JOIN instrumento i ON i.id_instrumento=v.id_instrumento ORDER BY v.fecha DESC LIMIT 100')->fetchAll();$reparaciones=$db->query('SELECT r.id_reparacion,r.estado,r.fecha_ingreso,r.costo,i.codigo_qr,i.tipo,u.nombre AS tecnico FROM reparacion r INNER JOIN instrumento i ON i.id_instrumento=r.id_instrumento INNER JOIN usuario u ON u.id_usuario=r.id_usuario ORDER BY r.fecha_ingreso DESC LIMIT 100')->fetchAll();$s=$db->prepare('SELECT estado,COUNT(*) cantidad FROM reparacion GROUP BY estado');$s->execute();$estados=$s->fetchAll();$titulo='Reportes';require __DIR__.'/../../includes/header.php';?>
