<section class="card mb-4" id="stock"><div class="card-header"><h3><i class="bi bi-box-seam"></i> Reporte de stock</h3></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Material</th><th class="stock">Stock</th><th class="stock">Mínimo</th></tr></thead><tbody><?php foreach($stock as $m): ?><tr class="<?=$m['stock']<=$m['stock_minimo']?'table-warning':''?>"><td><?=e($m['nombre'])?> <?php if($m['stock']<=$m['stock_minimo']): ?><span class="badge stock-min">Stock mínimo</span><?php endif; ?></td><td class="stock"><?=e((string)$m['stock'])?></td><td class="stock"><?=e((string)$m['stock_minimo'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
