<section class="card mb-4" id="reparaciones"><div class="card-header"><h3><i class="bi bi-tools"></i> Reparaciones por estado</h3></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Reparación</th><th>Instrumento</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach($reparaciones as $r): ?><tr><td>#<?=$r['id_reparacion']?></td><td><?=e($r['codigo_qr'].' - '.$r['tipo'])?></td><td><span class="badge-status status-<?=e($r['estado'])?>"><?=e(ucwords(str_replace('_',' ',$r['estado'])))?></span></td><td><?=e($r['fecha_ingreso'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php if($serie): ?><script src="<?=e(BASE_URL)?>/assets/vendor/chart.min.js"></script><script>const etiquetas=<?=json_encode(array_keys($serie),JSON_UNESCAPED_UNICODE)?>,valores=<?=json_encode(array_values($serie))?>;new Chart(document.getElementById('grafico-ingresos'),{type:'line',data:{labels:etiquetas,datasets:[{label:'Ingresos Bs',data:valores,borderColor:'#1976d2',backgroundColor:'#1976d233',fill:true,tension:.25}]},options:{responsive:true,maintainAspectRatio:false}});</script><?php endif; ?><?php require __DIR__.'/../../includes/footer.php';
